<?php require_admin();$stats=db_one("SELECT (SELECT COUNT(*) FROM students) students,(SELECT COUNT(*) FROM complaints) complaints,SUM(status='Pending') pending,SUM(status='In Progress') progress,SUM(status='Resolved') resolved,SUM(status='Closed') closed FROM complaints");$recent=db_all('SELECT c.*,s.name student_name,ca.category_name FROM complaints c JOIN students s ON s.id=c.student_id JOIN categories ca ON ca.id=c.category_id ORDER BY c.created_at DESC LIMIT 7');$pageTitle='Admin Dashboard';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4"><div class="small-muted">ADMINISTRATION</div><h1 class="section-title mb-0">Operations overview</h1><p class="text-secondary mb-0 mt-2">Monitor the flow of student concerns and keep responses moving.</p></div><div class="row g-3 mb-4"><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Students</div><div class="stat-value"><?= (int)$stats['students'] ?></div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Complaints</div><div class="stat-value"><?= (int)$stats['complaints'] ?></div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Pending</div><div class="stat-value text-warning"><?= (int)($stats['pending']??0) ?></div></div></div><div class="col-6 col-xl-3"><div class="card stat-card"><div class="stat-label">Resolved</div><div class="stat-value text-success"><?= (int)($stats['resolved']??0) ?></div></div></div></div><div class="card"><div class="card-header d-flex justify-content-between"><strong>Recent complaints</strong><a class="small text-decoration-none" href="<?=e(url('admin/complaints.php'))?>">View all</a></div><div class="table-responsive"><table class="table"><thead><tr><th>Complaint</th><th>Student</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php if(!$recent): ?><tr><td colspan="4"><div class="empty-state">No complaints have been submitted.</div></td></tr><?php else: foreach($recent as $row): ?><tr><td><a class="complaint-id" href="<?=e(url('admin/complaint.php?id='.$row['id']))?>"><?=e($row['complaint_id'])?></a><div><?=e($row['title'])?></div></td><td><?=e($row['student_name'])?><div class="small-muted"><?=e($row['category_name'])?></div></td><td><span class="fw-semibold <?=e(priority_class($row['priority']))?>"><?=e($row['priority'])?></span></td><td><span class="badge-soft <?=e(status_class($row['status']))?>"><?=e($row['status'])?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div></div>
